@Override
	public void handleSelectionRequest(EntityPlayerMP player, int primary, int secondary) {
		switch (primary) {
			case -1: { // clicked clear button
				tile.clearCraftMatrix();
				updateCraftMatrix();
				sendPacketToListeners(new PacketWorktableRecipeUpdate(tile));
				break;
			}
